import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"AI 创意广告全景","description":"","frontmatter":{},"headers":[],"relativePath":"guide/landscape.md","filePath":"guide/landscape.md","lastUpdated":1785729506000}'),o={name:"guide/landscape.md"};function s(n,t,h,l,i,p){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-创意广告全景" tabindex="-1">AI 创意广告全景 <a class="header-anchor" href="#ai-创意广告全景" aria-label="Permalink to &quot;AI 创意广告全景&quot;">​</a></h1><p>在钻进任何一个工具之前，先看清楚整块地形：一支广告由哪些部件组成，AI 分别能接管到什么程度。</p><h2 id="一支广告的部件清单" tabindex="-1">一支广告的部件清单 <a class="header-anchor" href="#一支广告的部件清单" aria-label="Permalink to &quot;一支广告的部件清单&quot;">​</a></h2><p>不管最终形态是 15 秒竖屏还是一张主图，拆开都是这几层：</p><table tabindex="0"><thead><tr><th>层</th><th>具体是什么</th><th>AI 的成熟度</th></tr></thead><tbody><tr><td><strong>策略层</strong></td><td>卖给谁、说什么、为什么他会信</td><td>低。AI 能帮你穷举角度，但判断哪条真的扎心，要人</td></tr><tr><td><strong>创意层</strong></td><td>Big Idea、一句 slogan、一个记忆点</td><td>中低。产出量大，但同质化严重，需要人做筛选和拔高</td></tr><tr><td><strong>脚本层</strong></td><td>分镜、台词、节奏</td><td>中高。结构化程度高，AI 写得很快，人做取舍</td></tr><tr><td><strong>视觉层</strong></td><td>画面、模特、场景、光影</td><td>高。这是 AI 最强的地方</td></tr><tr><td><strong>听觉层</strong></td><td>配音、配乐、音效</td><td>高。中文配音的自然度已经够用</td></tr><tr><td><strong>成片层</strong></td><td>剪辑、调色、字幕、导出</td><td>中。AI 能做粗剪，精修仍靠传统软件</td></tr></tbody></table><p>**结论：AI 在「执行」上强，在「判断」上弱。**越靠近上面（策略、创意），人的价值越高；越靠近下面（视觉、听觉），AI 的替代率越高。</p><div class="tip custom-block"><p class="custom-block-title">稳定</p><p>这个分层判断在可见的未来不会大变。工具会迭代，但「谁来决定说什么」和「谁来把它画出来」的分工是结构性的。</p></div><h2 id="三种典型的交付形态" tabindex="-1">三种典型的交付形态 <a class="header-anchor" href="#三种典型的交付形态" aria-label="Permalink to &quot;三种典型的交付形态&quot;">​</a></h2><p>不同形态的难度差异极大，接活时先分清是哪一类。</p><h3 id="一、静态视觉-主图、kv、海报" tabindex="-1">一、静态视觉（主图、KV、海报） <a class="header-anchor" href="#一、静态视觉-主图、kv、海报" aria-label="Permalink to &quot;一、静态视觉（主图、KV、海报）&quot;">​</a></h3><p><strong>难度：低。</strong> 单帧画面，不涉及时间连续性，AI 最擅长。</p><p>主要挑战是<strong>产品保真</strong>——生成模型很难精确复现一个真实存在的产品（logo 位置、瓶身弧度、材质反光）。常见解法是把真实产品图作为参考输入，让 AI 只生成背景与光环境，或者干脆生成背景后用传统软件合成产品。</p><h3 id="二、短视频-社媒-6–30-秒" tabindex="-1">二、短视频（社媒 6–30 秒） <a class="header-anchor" href="#二、短视频-社媒-6–30-秒" aria-label="Permalink to &quot;二、短视频（社媒 6–30 秒）&quot;">​</a></h3><p><strong>难度：中。</strong> 镜头少、节奏快，观众对连贯性的容忍度也相对高。</p><p>主要挑战是<strong>跨镜头一致性</strong>——同一个人物、同一个产品，在第 3 个镜头和第 7 个镜头得看起来是同一个。见 <a href="/method/brand-consistency">品牌一致性控制</a>。</p><h3 id="三、完整-tvc-30-秒以上、有叙事" tabindex="-1">三、完整 TVC（30 秒以上、有叙事） <a class="header-anchor" href="#三、完整-tvc-30-秒以上、有叙事" aria-label="Permalink to &quot;三、完整 TVC（30 秒以上、有叙事）&quot;">​</a></h3><p><strong>难度：高。</strong> 需要人物表演、情绪递进、镜头调度。</p><p>现阶段纯 AI 生成的完整 TVC，弱点集中在<strong>表演</strong>上：人物表情僵硬、动作幅度不自然、口型对不上。务实的做法是混合生产——AI 做空镜、产品特写、场景延展，实拍做人物表演。</p><h2 id="ai-介入的三种模式" tabindex="-1">AI 介入的三种模式 <a class="header-anchor" href="#ai-介入的三种模式" aria-label="Permalink to &quot;AI 介入的三种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>做法</th><th>适合</th></tr></thead><tbody><tr><td><strong>替代</strong></td><td>整条链路交给 AI，人只验收</td><td>预算极低、时效极紧、质量要求不高的批量素材</td></tr><tr><td><strong>增强</strong></td><td>AI 做发散和草稿，人做筛选和精修</td><td>绝大多数正经项目</td></tr><tr><td><strong>探索</strong></td><td>用 AI 快速试错，把可行方案交给传统流程正式制作</td><td>高预算项目的前期，AI 当作低成本的分镜可视化工具</td></tr></tbody></table><p>大部分人一开始都想用「替代」，做过两个项目后会退回「增强」。这不是失败，是找到了合理位置。</p><h2 id="常见的认知误区" tabindex="-1">常见的认知误区 <a class="header-anchor" href="#常见的认知误区" aria-label="Permalink to &quot;常见的认知误区&quot;">​</a></h2><p><strong>「Prompt 写得够好就能一次出片。」</strong> 不能。真实工作流是大量的生成—筛选—重生成。做 8 个镜头，生成三四十条素材是正常的。把废片率当成成本算进去，而不是当成失败。</p><p><strong>「AI 便宜。」</strong> 单条素材便宜，但要达到可交付的质量，消耗的次数和人工筛选时间都不低。AI 真正省的是<strong>试错成本</strong>和<strong>排期</strong>，不一定是总成本。</p><p><strong>「工具选对了就赢一半。」</strong> 主流工具的能力差距远小于使用者的差距。同一个模型，会拆分镜的人和不会的人，产出差一个量级。所以本站把 <a href="/method/">方法论</a> 放在 <a href="/tools/">工具地图</a> 前面。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>想知道具体怎么推进一个项目 → <a href="/method/workflow-sop">从 brief 到成片：完整链路 SOP</a></li><li>想看真实的拆解 → <a href="/cases/case-01-beverage-tvc">案例 01 · 饮料品牌短 TVC</a></li></ul>',27)])])}const b=a(o,[["render",s]]);export{g as __pageData,b as default};
